import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  logits: { fill: '#e3f2fd', stroke: '#1976d2' },
  max: { fill: '#fff3e0', stroke: '#f57c00' },
  shifted: { fill: '#e8f5e9', stroke: '#4caf50' },
  exp: { fill: '#e3f2fd', stroke: '#1976d2' },
  sum: { fill: '#fff3e0', stroke: '#f57c00' },
  probs: { fill: '#e8f5e9', stroke: '#4caf50' },
  accum: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_W = 200;
const MAT_H = 120;
const VEC_W = 320;
const VEC_H = 46;
const SCALAR_SIZE = 64;
const STEP_GAP = 150;
const BOX_TO_ROW = 110;
const ROW_GAP = 130;
const SHAPE_GAP = 56;
const SIDE_OFF = 220;

interface SoftmaxStep extends StepInfo {}
type SoftmaxVariant = 'naive' | 'safe' | 'online';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDownBetween(
  g: Gsel, x: number, yTop: number, targetTop: number, color = '#94a3b8', margin = 10
): void {
  if (targetTop - margin > yTop) {
    drawArrow(g as Sel, x, yTop, x, targetTop - margin, { color });
  }
}

function arrowHBetween(
  g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = 10
): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function arrowUpTo(
  g: Gsel, x: number, yBottom: number, targetBottom: number, color = '#94a3b8', margin = 10
): void {
  if (yBottom - margin > targetBottom + margin) {
    drawArrow(g as Sel, x, yBottom - margin, x, targetBottom + margin, { color });
  }
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 880
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.8 + 36, 240);
  const h = 32;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function matrixBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = MAT_W, h = MAT_H,
  dimTop?: string, dimLeft?: string
): void {
  const top = dimTop ?? (sub.includes(',') ? sub.split(',')[1].trim().replace(/\]/, '') : '');
  const left = dimLeft ?? (sub.includes(',') ? sub.split(',')[0].trim().replace(/\[/, '') : '');
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 6, dimTop: top, dimLeft: left,
  });
}

function vecBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string
): void {
  drawMatrixBlock(g as Sel, cx - VEC_W / 2, cy - VEC_H / 2, {
    width: VEC_W, height: VEC_H, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 1,
  });
}

function scalarBlock(g: Gsel, cx: number, cy: number, label: string, sub = ''): void {
  drawMatrixBlock(g as Sel, cx - SCALAR_SIZE / 2, cy - SCALAR_SIZE / 2, {
    width: SCALAR_SIZE, height: SCALAR_SIZE, label, sublabel: sub, fill: COLORS.max.fill, stroke: COLORS.max.stroke,
    cols: 1, rows: 1,
  });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const r = text.length > 2 ? 20 : 16;
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', r)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: text.length > 2 ? 10 : 13, weight: '700', color });
}

function indexLabel(g: Gsel, x: number, y: number, text: string, color: string, anchor: 'start' | 'middle' | 'end' = 'middle'): void {
  lbl(g, x, y, text, { size: 11, weight: '700', color, anchor });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): SoftmaxStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawHighlightRow(g: Gsel, cx: number, cy: number, w: number, h: number, row: number, rows: number, color: string): void {
  const cellH = (h - 2) / rows;
  const y = cy - h / 2 + 1 + row * cellH;
  g.append('rect').attr('x', cx - w / 2 + 1).attr('y', y).attr('width', w - 2).attr('height', cellH - 1)
    .attr('fill', color).attr('opacity', 0.25).attr('stroke', color).attr('stroke-width', 1);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Shared input/output steps
// ═══════════════════════════════════════════════════════════════════════════════

function renderInputStep(
  g: Gsel, yStart: number, seqLen: number, numClasses: number, hiRow: number
): { step: SoftmaxStep; y: number } {
  const stepId = 1;
  const gs = startGroup(g, 'step-input', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Input Logits',
    `logits [${seqLen}, ${numClasses}]`,
    COLORS.logits.fill, COLORS.logits.stroke);

  const rowY = hBottom + BOX_TO_ROW;
  matrixBlock(gs, CX, rowY, 'logits', `[${seqLen}, ${numClasses}]`, COLORS.logits.fill, COLORS.logits.stroke, MAT_W, MAT_H, String(numClasses), String(seqLen));
  drawHighlightRow(gs, CX, rowY, MAT_W, MAT_H, hiRow, 6, COLORS.logits.stroke);
  indexLabel(gs, CX - MAT_W / 2 - 10, rowY - MAT_H / 2 + (hiRow + 0.5) * (MAT_H / 6), 't', COLORS.logits.stroke, 'end');

  shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
    `logits [${seqLen}, ${numClasses}]`, COLORS.logits.stroke);

  const step = makeStep(stepId, 'Input', 'Input Logits',
    `logits [${seqLen}, ${numClasses}]`,
    'Softmax converts raw logits into a probability distribution over classes.',
    'step-input', COLORS.logits.stroke, COLORS.logits.fill,
    [`x = logits[t, :]  # [${numClasses}]`]);

  return { step, y: rowY + MAT_H / 2 + 28 + SHAPE_GAP + STEP_GAP };
}

function renderOutputStep(
  g: Gsel, yStart: number, seqLen: number, numClasses: number, hiRow: number, stepId: number
): { step: SoftmaxStep; y: number } {
  const gs = startGroup(g, 'step-output', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Output Probabilities',
    `probs [${seqLen}, ${numClasses}]`,
    COLORS.probs.fill, COLORS.probs.stroke);

  const rowY = hBottom + BOX_TO_ROW;
  matrixBlock(gs, CX, rowY, 'probs', `[${seqLen}, ${numClasses}]`, COLORS.probs.fill, COLORS.probs.stroke, MAT_W, MAT_H, String(numClasses), String(seqLen));
  drawHighlightRow(gs, CX, rowY, MAT_W, MAT_H, hiRow, 6, COLORS.probs.stroke);
  indexLabel(gs, CX - MAT_W / 2 - 10, rowY - MAT_H / 2 + (hiRow + 0.5) * (MAT_H / 6), 't', COLORS.probs.stroke, 'end');

  lbl(gs, CX + MAT_W / 2 + 14, rowY, 'sums to 1', { size: 10, color: COLORS.muted, anchor: 'start' });

  shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
    `probs [${seqLen}, ${numClasses}]`, COLORS.probs.stroke);

  const step = makeStep(stepId, 'Output', 'Output Probabilities',
    `probs [${seqLen}, ${numClasses}]`,
    'Each row of the output matrix is a valid probability distribution that sums to 1.',
    'step-output', COLORS.probs.stroke, COLORS.probs.fill,
    [`probs[t, :] = p  # sums to 1`]);

  return { step, y: rowY + MAT_H / 2 + 28 + SHAPE_GAP };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Naive renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderNaive(g: Gsel, yStart: number, seqLen: number, numClasses: number, hiRow: number): { steps: SoftmaxStep[]; y: number } {
  const steps: SoftmaxStep[] = [];

  // Step 1: input
  const input = renderInputStep(g, yStart, seqLen, numClasses, hiRow);
  steps.push(input.step);
  let y = input.y;

  // Step 2: exponentiate
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-exp', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Exponentiate',
      `e_i = exp(x_i)`,
      COLORS.exp.fill, COLORS.exp.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'x_t', `[${numClasses}]`, COLORS.logits.fill, COLORS.logits.stroke);
    opCircle(gs, CX, rowY, 'exp', COLORS.exp.stroke);
    vecBlock(gs, CX + SIDE_OFF, rowY, 'exp(x_t)', `[${numClasses}]`, COLORS.exp.fill, COLORS.exp.stroke);

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 20, rowY, COLORS.logits.stroke);
    arrowHBetween(gs, CX + 20, CX + SIDE_OFF - VEC_W / 2, rowY, COLORS.exp.stroke);

    shapeEq(gs, CX, rowY + VEC_H / 2 + 28,
      `e_i = exp(x_i)`, COLORS.exp.stroke);

    steps.push(makeStep(stepId, 'Exp', 'Exponentiate',
      `e_i = exp(x_i)`,
      'The naive variant exponentiates every logit directly.',
      'step-exp', COLORS.exp.stroke, COLORS.exp.fill,
      [`e = torch.exp(x)  # can overflow for large x`]));
    y = rowY + VEC_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: sum
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-sum', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Sum Exponentials',
      `S = Σ_i e_i`,
      COLORS.sum.fill, COLORS.sum.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX, rowY, 'exp(x_t)', `[${numClasses}]`, COLORS.exp.fill, COLORS.exp.stroke);
    opCircle(gs, CX, rowY + ROW_GAP / 2, 'Σ', COLORS.sum.stroke);
    scalarBlock(gs, CX, rowY + ROW_GAP, 'S', 'scalar');

    arrowDownBetween(gs, CX, rowY + VEC_H / 2, rowY + ROW_GAP / 2 - 20, COLORS.exp.stroke);
    arrowDownBetween(gs, CX, rowY + ROW_GAP / 2 + 20, rowY + ROW_GAP - SCALAR_SIZE / 2, COLORS.sum.stroke);

    shapeEq(gs, CX, rowY + ROW_GAP + SCALAR_SIZE / 2 + 28,
      `S = Σ_{i=0}^{${numClasses - 1}} e_i`, COLORS.sum.stroke);

    steps.push(makeStep(stepId, 'Sum', 'Sum Exponentials',
      `S = Σ_i e_i`,
      'Add up all the exponentials to get the normalization constant.',
      'step-sum', COLORS.sum.stroke, COLORS.sum.fill,
      [`S = e.sum()`]));
    y = rowY + ROW_GAP + SCALAR_SIZE / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: normalize
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Normalize',
      `p_i = e_i / S`,
      COLORS.probs.fill, COLORS.probs.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'exp(x_t)', `[${numClasses}]`, COLORS.exp.fill, COLORS.exp.stroke);
    opCircle(gs, CX, rowY, '÷', COLORS.probs.stroke);
    vecBlock(gs, CX + SIDE_OFF, rowY, 'probs_t', `[${numClasses}]`, COLORS.probs.fill, COLORS.probs.stroke);
    scalarBlock(gs, CX, rowY + ROW_GAP, 'S', 'scalar');

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 16, rowY, COLORS.exp.stroke);
    arrowHBetween(gs, CX + 16, CX + SIDE_OFF - VEC_W / 2, rowY, COLORS.probs.stroke);
    arrowUpTo(gs, CX, rowY + ROW_GAP, rowY + 16, COLORS.sum.stroke);

    shapeEq(gs, CX, rowY + ROW_GAP + SCALAR_SIZE / 2 + 28,
      `p_i = e_i / S`, COLORS.probs.stroke);

    steps.push(makeStep(stepId, 'Norm', 'Normalize',
      `p_i = e_i / S`,
      'Divide each exponential by the sum to obtain probabilities.',
      'step-norm', COLORS.probs.stroke, COLORS.probs.fill,
      [`p = e / S`])); // shape broadcast
    y = rowY + ROW_GAP + SCALAR_SIZE / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 5: output
  const output = renderOutputStep(g, y, seqLen, numClasses, hiRow, 5);
  steps.push(output.step);
  y = output.y;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Safe renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderSafe(g: Gsel, yStart: number, seqLen: number, numClasses: number, hiRow: number): { steps: SoftmaxStep[]; y: number } {
  const steps: SoftmaxStep[] = [];

  const input = renderInputStep(g, yStart, seqLen, numClasses, hiRow);
  steps.push(input.step);
  let y = input.y;

  // Step 2: max
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-max', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Find Max',
      `m = max(x_t)`,
      COLORS.max.fill, COLORS.max.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'x_t', `[${numClasses}]`, COLORS.logits.fill, COLORS.logits.stroke);
    opCircle(gs, CX, rowY, 'max', COLORS.max.stroke);
    scalarBlock(gs, CX + SIDE_OFF, rowY, 'm', 'scalar');

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 20, rowY, COLORS.logits.stroke);
    arrowHBetween(gs, CX + 20, CX + SIDE_OFF - SCALAR_SIZE / 2, rowY, COLORS.max.stroke);

    shapeEq(gs, CX, rowY + SCALAR_SIZE / 2 + 28,
      `m = max(x_t)`, COLORS.max.stroke);

    steps.push(makeStep(stepId, 'Max', 'Find Max',
      `m = max(x_t)`,
      'Subtracting the maximum logit prevents exponent overflow.',
      'step-max', COLORS.max.stroke, COLORS.max.fill,
      [`m = x.max()`]));
    y = rowY + SCALAR_SIZE / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: subtract max
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-shift', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Subtract Max',
      `z_i = x_i - m`,
      COLORS.shifted.fill, COLORS.shifted.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'x_t', `[${numClasses}]`, COLORS.logits.fill, COLORS.logits.stroke);
    opCircle(gs, CX, rowY, '-', COLORS.shifted.stroke);
    vecBlock(gs, CX + SIDE_OFF, rowY, 'z_t', `[${numClasses}]`, COLORS.shifted.fill, COLORS.shifted.stroke);
    const mY = rowY - 70;
    scalarBlock(gs, CX, mY, 'm', 'scalar');

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 16, rowY, COLORS.logits.stroke);
    arrowHBetween(gs, CX + 16, CX + SIDE_OFF - VEC_W / 2, rowY, COLORS.shifted.stroke);
    arrowDownBetween(gs, CX, mY + SCALAR_SIZE / 2, rowY - 16, COLORS.max.stroke);

    shapeEq(gs, CX, rowY + VEC_H / 2 + 28,
      `z_i = x_i - m`, COLORS.shifted.stroke);

    steps.push(makeStep(stepId, 'Shift', 'Subtract Max',
      `z_i = x_i - m`,
      'Shift every logit by the row maximum for numerical stability.',
      'step-shift', COLORS.shifted.stroke, COLORS.shifted.fill,
      [`z = x - m  # m is broadcast over classes`]));
    y = rowY + VEC_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: exponentiate
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-exp', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Exponentiate',
      `e_i = exp(z_i)`,
      COLORS.exp.fill, COLORS.exp.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'z_t', `[${numClasses}]`, COLORS.shifted.fill, COLORS.shifted.stroke);
    opCircle(gs, CX, rowY, 'exp', COLORS.exp.stroke);
    vecBlock(gs, CX + SIDE_OFF, rowY, 'exp(z_t)', `[${numClasses}]`, COLORS.exp.fill, COLORS.exp.stroke);

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 20, rowY, COLORS.shifted.stroke);
    arrowHBetween(gs, CX + 20, CX + SIDE_OFF - VEC_W / 2, rowY, COLORS.exp.stroke);

    shapeEq(gs, CX, rowY + VEC_H / 2 + 28,
      `e_i = exp(z_i)`, COLORS.exp.stroke);

    steps.push(makeStep(stepId, 'Exp', 'Exponentiate',
      `e_i = exp(z_i)`,
      'After shifting, the largest value is 0, so exp never overflows.',
      'step-exp', COLORS.exp.stroke, COLORS.exp.fill,
      [`e = torch.exp(z)`]));
    y = rowY + VEC_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 5: sum + normalize
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Sum and Normalize',
      `p_i = e_i / Σ_j e_j`,
      COLORS.probs.fill, COLORS.probs.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'exp(z_t)', `[${numClasses}]`, COLORS.exp.fill, COLORS.exp.stroke);
    opCircle(gs, CX, rowY, '÷', COLORS.probs.stroke);
    vecBlock(gs, CX + SIDE_OFF, rowY, 'probs_t', `[${numClasses}]`, COLORS.probs.fill, COLORS.probs.stroke);
    scalarBlock(gs, CX, rowY + ROW_GAP, 'S', 'scalar');

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 16, rowY, COLORS.exp.stroke);
    arrowHBetween(gs, CX + 16, CX + SIDE_OFF - VEC_W / 2, rowY, COLORS.probs.stroke);
    arrowUpTo(gs, CX, rowY + ROW_GAP, rowY + 16, COLORS.sum.stroke);

    shapeEq(gs, CX, rowY + ROW_GAP + SCALAR_SIZE / 2 + 28,
      `p_i = e_i / Σ_j e_j`, COLORS.probs.stroke);

    steps.push(makeStep(stepId, 'Norm', 'Sum and Normalize',
      `p_i = e_i / Σ_j e_j`,
      'Divide the shifted exponentials by their sum to get probabilities.',
      'step-norm', COLORS.probs.stroke, COLORS.probs.fill,
      [`S = e.sum()`, `p = e / S`]));
    y = rowY + ROW_GAP + SCALAR_SIZE / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 6: output
  const output = renderOutputStep(g, y, seqLen, numClasses, hiRow, 6);
  steps.push(output.step);
  y = output.y;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Online renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderOnline(g: Gsel, yStart: number, seqLen: number, numClasses: number, hiRow: number): { steps: SoftmaxStep[]; y: number } {
  const steps: SoftmaxStep[] = [];

  const input = renderInputStep(g, yStart, seqLen, numClasses, hiRow);
  steps.push(input.step);
  let y = input.y;

  // Step 2: single-pass accumulators
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-accum', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Single-Pass Accumulate',
      `m_i = max(m_{i-1}, x_i);  d_i = f(d_{i-1}, m_{i-1}, x_i, m_i)`,
      COLORS.accum.fill, COLORS.accum.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'x_t', `[${numClasses}]`, COLORS.logits.fill, COLORS.logits.stroke);
    scalarBlock(gs, CX + 80, rowY - 50, 'm', 'running max');
    scalarBlock(gs, CX + 80, rowY + 50, 'd', 'running sum');

    // sweep arrow from vector to between the two scalars
    drawArrow(g as Sel, CX - SIDE_OFF + VEC_W / 2, rowY, CX + 80 - SCALAR_SIZE / 2 - 10, rowY, { color: COLORS.accum.stroke });

    lbl(gs, CX + 160, rowY, `for i = 0 … ${numClasses - 1}`, {
      size: 10, color: COLORS.muted, anchor: 'start'
    });
    lbl(gs, CX + 160, rowY + 18, 'm_i = max(m_{i-1}, x_i)', {
      size: 9, color: COLORS.muted, anchor: 'start', font: 'monospace'
    });
    lbl(gs, CX + 160, rowY + 34, 'd_i = d_{i-1}·e^{m_{i-1}-m_i} + e^{x_i-m_i}', {
      size: 9, color: COLORS.muted, anchor: 'start', font: 'monospace'
    });

    shapeEq(gs, CX, rowY + 90,
      `online:  m, d = accumulate(x_t)`, COLORS.accum.stroke);

    steps.push(makeStep(stepId, 'Accum', 'Single-Pass Accumulate',
      `m, d = accumulate(x_t)`,
      'Online softmax updates the running maximum and a compensated sum in one pass, reducing memory traffic.',
      'step-accum', COLORS.accum.stroke, COLORS.accum.fill,
      [`m, d = 0, 0`,
       `for i in range(V):`,
       `    m_prev = m`,
       `    m = max(m, x[i])`,
       `    d = d * exp(m_prev - m) + exp(x[i] - m)`]));
    y = rowY + 90 + SHAPE_GAP + STEP_GAP;
  }

  // Step 3: normalize
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Normalize',
      `p_i = exp(x_i - m) / d`,
      COLORS.probs.fill, COLORS.probs.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    vecBlock(gs, CX - SIDE_OFF, rowY, 'x_t', `[${numClasses}]`, COLORS.logits.fill, COLORS.logits.stroke);
    opCircle(gs, CX, rowY, '÷', COLORS.probs.stroke);
    vecBlock(gs, CX + SIDE_OFF, rowY, 'probs_t', `[${numClasses}]`, COLORS.probs.fill, COLORS.probs.stroke);
    const mY = rowY - 70;
    scalarBlock(gs, CX, mY, 'm', 'scalar');
    scalarBlock(gs, CX, rowY + ROW_GAP, 'd', 'scalar');

    arrowHBetween(gs, CX - SIDE_OFF + VEC_W / 2, CX - 16, rowY, COLORS.logits.stroke);
    arrowHBetween(gs, CX + 16, CX + SIDE_OFF - VEC_W / 2, rowY, COLORS.probs.stroke);
    arrowDownBetween(gs, CX, mY + SCALAR_SIZE / 2, rowY - 16, COLORS.max.stroke);
    arrowUpTo(gs, CX, rowY + ROW_GAP, rowY + 16, COLORS.accum.stroke);

    shapeEq(gs, CX, rowY + ROW_GAP + SCALAR_SIZE / 2 + 28,
      `p_i = exp(x_i - m) / d`, COLORS.probs.stroke);

    steps.push(makeStep(stepId, 'Norm', 'Normalize',
      `p_i = exp(x_i - m) / d`,
      'Use the final running max and sum to normalize the original logits.',
      'step-norm', COLORS.probs.stroke, COLORS.probs.fill,
      [`p = torch.exp(x - m) / d`]));
    y = rowY + ROW_GAP + SCALAR_SIZE / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // Step 4: output
  const output = renderOutputStep(g, y, seqLen, numClasses, hiRow, 4);
  steps.push(output.step);
  y = output.y;

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderSoftmaxDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const numClasses = Number(params.num_classes) || 1000;
  const variant = String(params.variant || 'safe') as SoftmaxVariant;
  const hiRow = 2;

  const stepsMeta: SoftmaxStep[] = [];
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'Softmax', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8,
    `${variant === 'naive' ? 'Naive' : variant === 'online' ? 'Online' : 'Safe (subtract-max)'} softmax — logits to probabilities`,
    { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `seq_len: ${seqLen}`, `num_classes: ${numClasses}`, `variant: ${variant.toUpperCase()}`,
  ]);
  y += 32;

  const { steps, y: finalY } = variant === 'naive'
    ? renderNaive(g, y, seqLen, numClasses, hiRow)
    : variant === 'online'
      ? renderOnline(g, y, seqLen, numClasses, hiRow)
      : renderSafe(g, y, seqLen, numClasses, hiRow);
  stepsMeta.push(...steps);
  y = finalY;

  // ── Footer ─────────────────────────────────────────────────────────────────
  y += 32;
  const insightText = variant === 'naive'
    ? 'Naive softmax is the textbook definition, but exponentiating large logits can overflow. It is mainly useful for understanding the math.'
    : variant === 'online'
      ? 'Online softmax computes the normalizer in a single pass over the data. This reduces memory bandwidth and is the building block of Flash Attention’s online softmax kernel.'
      : 'Safe softmax subtracts the maximum logit before exponentiation. This eliminates overflow without changing the result and is the default in PyTorch and most deep-learning frameworks.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = `Output shape is [${seqLen}, ${numClasses}]. No learned parameters. The dominant cost is the ${(seqLen * numClasses).toLocaleString()} exponentiations per forward pass; safe/online variants add only a cheap max reduction.`;
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'matmul', 'MatMul');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'cross-entropy', 'Cross-Entropy');
  y += 72;

  const codeTitle = `Softmax — ${variant === 'naive' ? 'Naive' : variant === 'online' ? 'Online' : 'Safe'} (Python)`;
  const codeLines = variant === 'naive'
    ? [`# Naive softmax (can overflow)`,
       `def softmax_naive(x):`,
       `    e = torch.exp(x)`,
       `    return e / e.sum(dim=-1, keepdim=True)`]
    : variant === 'online'
      ? [`# Online softmax (single pass)`,
         `def softmax_online(x):`,
         `    m, d = -float('inf'), 0`,
         `    for xi in x:`,
         `        m_prev = m`,
         `        m = max(m, xi)`,
         `        d = d * exp(m_prev - m) + exp(xi - m)`,
         `    return exp(x - m) / d`]
      : [`# Safe softmax (subtract max)`,
         `def softmax_safe(x):`,
         `    z = x - x.max(dim=-1, keepdim=True).values`,
         `    e = torch.exp(z)`,
         `    return e / e.sum(dim=-1, keepdim=True)`];

  drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160, codeTitle,
    [`${variant === 'naive' ? 'Naive' : variant === 'online' ? 'Online' : 'Safe'} softmax — logits[${seqLen},${numClasses}] → probs[${seqLen},${numClasses}]`], codeLines);

  return { width: W, height: y + 160, steps: stepsMeta };
}
